# Which vault key (namespace `movies` in the operator's Touch ID vault) feeds which key of which
# Kubernetes Secret. NAMES ONLY -- the values never enter git. Pushed by infra/bin/push-k8s-secrets.
# The vault is the source of truth; the Secrets are copies (no more building them from .env.local).
#
# <namespace>/<secret>  <SECRET_KEY>  <VAULT_KEY>
# A row whose vault key does not exist yet is skipped (the Secret keeps its current value), so the
# map can list everything now and fill in as each credential is rotated.
kinowo/web-secrets      APPLICATION_SECRET            KINOWO_WEB_APPLICATION_SECRET
kinowo/web-secrets      GOOGLE_CLIENT_ID              KINOWO_GOOGLE_CLIENT_ID
kinowo/web-secrets      GOOGLE_CLIENT_SECRET          KINOWO_GOOGLE_CLIENT_SECRET
kinowo/web-secrets      FACEBOOK_APP_ID               KINOWO_FACEBOOK_APP_ID
kinowo/web-secrets      FACEBOOK_APP_SECRET           KINOWO_FACEBOOK_APP_SECRET
kinowo/web-secrets      MONGODB_URI                   KINOWO_MONGODB_URI
kinowo/web-secrets      OMDB_API_KEY                  OMDB_API_KEY
kinowo/web-secrets      SENTRY_DSN                    KINOWO_SENTRY_DSN
kinowo/web-secrets      TMDB_API_KEY                  TMDB_API_KEY
kinowo/worker-secrets   APPLICATION_SECRET            KINOWO_WORKER_APPLICATION_SECRET
kinowo/worker-secrets   MONGODB_URI                   KINOWO_MONGODB_URI
kinowo/worker-secrets   OMDB_API_KEY                  OMDB_API_KEY
kinowo/worker-secrets   SENTRY_DSN                    KINOWO_SENTRY_DSN
kinowo/worker-secrets   TMDB_API_KEY                  TMDB_API_KEY
kinowo/worker-secrets   ZYTE_API_KEY                  ZYTE_API_KEY
